package com.constructioncost.nativeapp.data.local

import androidx.room.Entity
import androidx.room.ColumnInfo
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey

@Entity(tableName = "projects")
internal data class ProjectEntity(@PrimaryKey val id: String, val name: String, val revision: Long, val archived: Boolean)
@Entity(tableName = "project_deletions")
internal data class ProjectDeletionEntity(@PrimaryKey val projectId: String, val phase: String, val filesJson: String, val startedAt: Long)
@Entity(tableName = "budgets", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"])], indices = [Index("projectId", unique = true)])
internal data class BudgetEntity(@PrimaryKey val id: String, val projectId: String, val amountPaise: Long)
@Entity(tableName = "classifications", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"]), ForeignKey(entity = ClassificationEntity::class, parentColumns = ["id"], childColumns = ["parentId"])], indices = [Index("projectId"), Index("parentId")])
internal data class ClassificationEntity(@PrimaryKey val id: String, val projectId: String, val name: String, val kind: String, val parentId: String?, val sortOrder: Int, val archived: Boolean, val nature: String)
@Entity(tableName = "vendors", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"])], indices = [Index("projectId")])
internal data class VendorEntity(@PrimaryKey val id: String, val projectId: String, val name: String, val note: String)
@Entity(tableName = "commitments", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"]), ForeignKey(entity = VendorEntity::class, parentColumns = ["id"], childColumns = ["vendorId"])], indices = [Index("projectId"), Index("vendorId")])
internal data class CommitmentEntity(@PrimaryKey val id: String, val projectId: String, val title: String, val amountPaise: Long, val vendorId: String?, val date: String, val revision: Long, val archived: Boolean, @ColumnInfo(defaultValue = "''") val note: String = "", @ColumnInfo(defaultValue = "''") val calculationJson: String = "")
@Entity(tableName = "instalments", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"]), ForeignKey(entity = CommitmentEntity::class, parentColumns = ["id"], childColumns = ["commitmentId"]), ForeignKey(entity = VendorEntity::class, parentColumns = ["id"], childColumns = ["vendorId"])], indices = [Index("projectId", "dueDate"), Index("commitmentId"), Index("vendorId")])
internal data class InstalmentEntity(@PrimaryKey val id: String, val projectId: String, val title: String, val amountPaise: Long, val dueDate: String, val commitmentId: String?, val vendorId: String?, val cancelled: Boolean, val remind: Boolean, val revision: Long, @ColumnInfo(defaultValue = "''") val note: String = "")
@Entity(tableName = "expenses", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"]), ForeignKey(entity = VendorEntity::class, parentColumns = ["id"], childColumns = ["vendorId"]), ForeignKey(entity = CommitmentEntity::class, parentColumns = ["id"], childColumns = ["commitmentId"]), ForeignKey(entity = InstalmentEntity::class, parentColumns = ["id"], childColumns = ["instalmentId"])], indices = [Index("projectId", "date"), Index("vendorId"), Index("commitmentId"), Index("instalmentId"), Index("idempotencyKey", unique = true)])
internal data class ExpenseEntity(@PrimaryKey val id: String, val projectId: String, val description: String, val amountPaise: Long, val date: String, val vendorId: String?, val note: String, val mode: String, val calculationJson: String, val revision: Long, val voided: Boolean, val commitmentId: String?, val instalmentId: String?, val idempotencyKey: String, val requestJson: String, @ColumnInfo(defaultValue = "''") val invoiceNumber: String = "")
@Entity(tableName = "expense_lines", foreignKeys = [ForeignKey(entity = ExpenseEntity::class, parentColumns = ["id"], childColumns = ["expenseId"])], indices = [Index("expenseId")])
internal data class ExpenseLineEntity(@PrimaryKey val id: String, val expenseId: String, val description: String, val amountPaise: Long, val mode: String, val quantity: String?, val rate: String?, val multiplier: String, val quantityUnit: String, val rateUnit: String, val legacyJson: String, @ColumnInfo(defaultValue = "''") val nature: String)
@Entity(tableName = "classification_allocations", foreignKeys = [ForeignKey(entity = ExpenseEntity::class, parentColumns = ["id"], childColumns = ["expenseId"]), ForeignKey(entity = ClassificationEntity::class, parentColumns = ["id"], childColumns = ["classificationId"])], indices = [Index("expenseId"), Index("classificationId"), Index(value = ["expenseId", "classificationId", "dimension"], unique = true)])
internal data class ClassificationAllocationEntity(@PrimaryKey val id: String, val expenseId: String, val classificationId: String, val dimension: String, val amountPaise: Long)
@Entity(tableName = "planned_classifications", foreignKeys = [ForeignKey(entity = ClassificationEntity::class, parentColumns = ["id"], childColumns = ["classificationId"]), ForeignKey(entity = CommitmentEntity::class, parentColumns = ["id"], childColumns = ["commitmentId"]), ForeignKey(entity = InstalmentEntity::class, parentColumns = ["id"], childColumns = ["instalmentId"])], indices = [Index("classificationId"), Index("commitmentId", "classificationId", unique = true), Index("instalmentId", "classificationId", unique = true)])
internal data class PlannedClassificationEntity(@PrimaryKey val id: String, val classificationId: String, val commitmentId: String?, val instalmentId: String?)
@Entity(tableName = "payments", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"]), ForeignKey(entity = VendorEntity::class, parentColumns = ["id"], childColumns = ["vendorId"]), ForeignKey(entity = InstalmentEntity::class, parentColumns = ["id"], childColumns = ["instalmentId"]), ForeignKey(entity = PaymentEntity::class, parentColumns = ["id"], childColumns = ["originalPaymentId"])], indices = [Index("projectId", "date"), Index("vendorId"), Index("instalmentId"), Index("originalPaymentId"), Index("idempotencyKey", unique = true)])
internal data class PaymentEntity(@PrimaryKey val id: String, val projectId: String, val amountPaise: Long, val date: String, val vendorId: String?, val reference: String, val note: String, val kind: String, val originalPaymentId: String?, val instalmentId: String?, val idempotencyKey: String, val requestJson: String)
@Entity(tableName = "payment_allocations", foreignKeys = [ForeignKey(entity = PaymentEntity::class, parentColumns = ["id"], childColumns = ["paymentId"]), ForeignKey(entity = ExpenseEntity::class, parentColumns = ["id"], childColumns = ["expenseId"])], indices = [Index("paymentId"), Index("expenseId"), Index(value = ["paymentId", "expenseId"], unique = true)])
internal data class PaymentAllocationEntity(@PrimaryKey val id: String, val paymentId: String, val expenseId: String, val amountPaise: Long)
@Entity(tableName = "attachments", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"]), ForeignKey(entity = AttachmentEntity::class, parentColumns = ["id"], childColumns = ["parentId"])], indices = [Index("projectId"), Index("parentId"), Index("storageName", unique = true)])
internal data class AttachmentEntity(@PrimaryKey val id: String, val projectId: String, val name: String, val mimeType: String, val size: Long, val sha256: String, val storageName: String, val createdAt: Long, val revision: Long, val parentId: String?, @ColumnInfo(defaultValue = "''") val category: String = "", @ColumnInfo(defaultValue = "''") val status: String = "", @ColumnInfo(defaultValue = "''") val revisionLabel: String = "", @ColumnInfo(defaultValue = "''") val work: String = "", @ColumnInfo(defaultValue = "''") val place: String = "", @ColumnInfo(defaultValue = "''") val notes: String = "")
@Entity(tableName = "activity_entries", foreignKeys = [ForeignKey(entity = ProjectEntity::class, parentColumns = ["id"], childColumns = ["projectId"])], indices = [Index("projectId", "date")])
internal data class ActivityEntity(@PrimaryKey val id: String, val projectId: String, val title: String, val date: String, val note: String, val revision: Long)
@Entity(tableName = "attachment_links", foreignKeys = [ForeignKey(entity = AttachmentEntity::class, parentColumns = ["id"], childColumns = ["attachmentId"]), ForeignKey(entity = ExpenseEntity::class, parentColumns = ["id"], childColumns = ["expenseId"]), ForeignKey(entity = PaymentEntity::class, parentColumns = ["id"], childColumns = ["paymentId"]), ForeignKey(entity = ActivityEntity::class, parentColumns = ["id"], childColumns = ["noteId"])], indices = [Index("attachmentId"), Index("expenseId"), Index("paymentId"), Index("noteId")])
internal data class AttachmentLinkEntity(@PrimaryKey val id: String, val attachmentId: String, val expenseId: String?, val paymentId: String?, val noteId: String?)
@Entity(tableName = "reminders", foreignKeys = [ForeignKey(entity = InstalmentEntity::class, parentColumns = ["id"], childColumns = ["instalmentId"])], indices = [Index("instalmentId", unique = true)])
internal data class ReminderEntity(@PrimaryKey val id: String, val instalmentId: String, val enabled: Boolean, @ColumnInfo(defaultValue = "3") val leadDays: Int = 3)
@Entity(tableName = "audit_records", indices = [Index("recordId", "createdAt")])
internal data class AuditEntity(@PrimaryKey val id: String, val recordType: String, val recordId: String, val action: String, val beforeJson: String, val afterJson: String, val createdAt: Long)
@Entity(tableName = "import_records")
internal data class ImportEntity(@PrimaryKey val id: String, val source: String, val originalJson: String, val createdAt: Long)
